        "scope_summary": "Sitio web corporativo y de captación para ASTRAEUS Cohetería Experimental (U.A.B.C Mexicali). Incluye Landing Page cinemática de alto impacto orientada a la atracción de patrocinadores y difusión del lanzamiento Octubre 2026, Galería interactiva para equipo/tecnología y Formulario de vinculación para patrocinadores.",
        "implementation_description": "Desarrollo en 4 fases de pago (25% cada una):\n\n\n\n1. **Fase 1 (25% = MXN $2,725):** Arquitectura inicial, maquetación visual tipo jeskojets y despliegue de vista previa privada en subdominio `astraeus.lmwares.com`.\n\n2. **Fase 2 (25% = MXN $2,725):** Integración de Galería de prototipos/equipo y Formulario de captación de patrocinadores con persistencia en panel.\n\n3. **Fase 3 (25% = MXN $2,725):** Revisión privada con el cliente y ajuste de contenidos para la retransmisión en vivo.\n\n4. **Fase 4 (25% = MXN $2,725):** Verificación final, preparación de compuerta de publicación y puesta en marcha oficial.",
        "recurring_description": "Mantenimiento operativo de MXN $900/mes (comienza únicamente al publicar el sitio en vivo). Incluye infraestructura Cloudflare, SSL, protección anti-spam Turnstile y soporte técnico de disponibilidad.",
