 ILUSTRATIVO, CONSTARÁ DE UNA LANDING ATRACTIVA Y MUY VISUAL; UNA GALERÍA DONDE MOSTRAREMOS A NUESTRO EQUIPO Y LA TECNOLOGÍA A BORDO, Y UN FORMULARIO PARA LOS INTERESADOS EN APOYAR AL EQUIPO.\"}}",
        "assigned_by": "whomelex@gmail.com",
